def aplicar(sits):
    """Acrescenta o perfil às fichas comuns e junta as fichas próprias."""
    por_id = {s['id']: s for s in sits}
    for id_ in COMUNS:
        por_id[id_]['perfis'] = por_id[id_]['perfis'] + list(EB)
    return sits + SITUACOES
